#!/usr/bin/env bash
# Build, create or refresh the tracking issue for a chain.
#
#   .claude/skills/add-chain/tracking-issue.sh <chain> [RustVariant]                 # print the body
#   .claude/skills/add-chain/tracking-issue.sh <chain> [RustVariant] --create        # open the issue
#   .claude/skills/add-chain/tracking-issue.sh <chain> [RustVariant] --update <n>    # refresh issue #n
#
# The issue has one section per milestone (M0-M6), each a task list, so GitHub
# shows progress. The M1 wiring list is generated by check-wiring.sh from the
# repo's current state, between two markers; --update replaces only that block
# and keeps every box ticked by hand elsewhere in the issue.
set -euo pipefail

usage() { echo "usage: tracking-issue.sh <chain> [RustVariant] [--create | --update <issue>]" >&2; exit 2; }
[ $# -ge 1 ] || usage
chain="$1"; shift
variant="$(printf '%s' "${chain:0:1}" | tr '[:lower:]' '[:upper:]')${chain:1}"
if [ $# -ge 1 ] && [ "${1#--}" = "$1" ]; then variant="$1"; shift; fi
mode=print issue=""
case "${1:-}" in
  "") ;;
  --create) mode=create ;;
  --update) mode=update; issue="${2:-}"; [ -n "$issue" ] || usage ;;
  *) usage ;;
esac

here="$(cd "$(dirname "$0")" && pwd)"
root="$(git -C "$here" rev-parse --show-toplevel)"
upper="$(printf '%s' "$chain" | tr '[:lower:]' '[:upper:]')"
start='<!-- add-chain:wiring:start -->'
end='<!-- add-chain:wiring:end -->'

wiring_block() {
  local out summary
  # check-wiring.sh exits 1 while touch points are missing; that's expected here.
  out="$(CHECK_WIRING_FORMAT=markdown "$here/check-wiring.sh" "$chain" "$variant" || true)"
  summary="$(printf '%s\n' "$out" | tail -n 1)"
  printf '%s\n' "$start"
  printf '%s\n' "$out" | sed '$d'
  # shellcheck disable=SC2016 # the backticks are markdown, not command substitution
  printf '\n_Checked by `check-wiring.sh %s` at `%s` on %s: %s._\n' \
    "$chain" "$(git -C "$root" rev-parse --short HEAD)" "$(date -u +%Y-%m-%d)" "$summary"
  printf '%s\n' "$end"
}

# Replaces the block between the markers on stdin with a fresh one. The block is
# passed through the environment because awk -v would interpret backslashes.
replace_wiring() {
  BLOCK="$(wiring_block)" S="$start" E="$end" awk '
    $0 == ENVIRON["S"] { print ENVIRON["BLOCK"]; skip = 1; next }
    $0 == ENVIRON["E"] { skip = 0; next }
    !skip              { print }
  '
}

body() {
  cat <<EOF
<!-- add-chain:tracking $chain -->
Tracks support for **$variant** (\`visualsign-$chain\`, proto \`CHAIN_$upper\`) from first PR to
production. Created by the \`add-chain\` skill. Tick boxes by hand except in M1, which
\`.claude/skills/add-chain/tracking-issue.sh $chain --update <this issue>\` regenerates.
Support is complete when every box is ticked or struck through with a reason.

## M0 Scope and policy

- [ ] Proto slot claimed: \`CHAIN_$upper = <n>\` (open PRs checked, see wiring.md step 3)
- [ ] Default-on or opt-in decided and stated in the PR
- [ ] Network-trust convention decided (signed, or "Declared network (unsigned)")
- [ ] C dependencies stated, with \`cargo tree -p visualsign-$chain -e normal,build --target aarch64-apple-ios -i cc\`
- [ ] Reference crate chosen; vector sources listed with immutable pins

## M1 Wiring

$(wiring_block)

## M2 Parser safety and tests (ship with the chain PR)

- [ ] Encoded size capped before decoding, with a test
- [ ] Structural and recursion caps, with tests
- [ ] Amplification ratio measured on the largest allowed input and stated
- [ ] Shows only what the signature commits to; refused modes have tests
- [ ] Fails closed on unknown types, unknown fields and trailing bytes, with tests
- [ ] No panics on input; checked arithmetic for amounts
- [ ] Pinned-provenance vectors
- [ ] \`REGEN_FIXTURES\` goldens
- [ ] \`review_*\` regression tests for each behaviour-changing review finding
- [ ] Differential oracle as a dev-dependency (or the reason there is none)

## M3 Property tests

- [ ] \`src/chain_parsers/visualsign-$chain/tests/proptest_$chain.rs\`
- [ ] Runs in CI under the \`test:proptest\` label (pattern: \`proptest-solana.yml\`)
- [ ] Regressions file committed

## M4 Fuzzing

- [ ] \`src/chain_parsers/visualsign-$chain/fuzz/\` with a \`fuzz_transaction_string\` target
- [ ] Runs in CI under the \`test:fuzz\` label (pattern: \`fuzz-solana.yml\`)
- [ ] Corpus seeded from the test fixtures

## M5 iOS (C-free)

- [ ] No \`cc\` in the normal+build graph for \`aarch64-apple-ios\`, or the C dependency is named and justified
- [ ] In \`APPLE_NO_C_CRATES\` and passing \`make -C src apple-silicon-check\` (once that target exists)

## M6 Production

- [ ] Downstream integration named and linked (who sends this chain's payloads)
- [ ] Default-on in parser_app, http-server and the images (if it started opt-in)
- [ ] Changelog entry published

## Links

- PRs:
EOF
}

case "$mode" in
  print) body ;;
  create)
    label_args=()
    if gh label list --limit 200 --json name --jq '.[].name' | grep -qx "chain:$chain"; then
      label_args=(--label "chain:$chain")
    fi
    body | gh issue create --title "Chain support: $variant" --body-file - "${label_args[@]}"
    ;;
  update)
    current="$(gh issue view "$issue" --json body --jq .body)"
    if ! printf '%s\n' "$current" | grep -qF "$start"; then
      echo "issue #$issue has no $start marker; not an add-chain tracking issue" >&2; exit 1
    fi
    printf '%s\n' "$current" | replace_wiring | gh issue edit "$issue" --body-file -
    ;;
esac
